article_details=[
 ('Business','Three Habits For A Healthier Business Cash Flow',photos['desk'],'Notebook and business paperwork',[('Keep A Simple Forecast','A short rolling forecast can help you understand upcoming commitments. Start with the money you expect to receive, then note your regular and occasional expenses.'),('Make Invoicing A Routine','Consistent invoicing and clear payment terms help you understand what is outstanding. Set aside time each week to review payments and follow up where appropriate.'),('Review The Numbers Regularly','A small, regular review is often more useful than an occasional deep dive. Look for changes in sales, expenses and cash balances, then ask for advice when something is unclear.')]),
 ('Bookkeeping','A Simpler Routine For Staying On Top Of Your Books',photos['workspace'],'Workspace with natural light',[('Keep Records In One Place','Choose a consistent process for collecting receipts, invoices and key business records. A simple system is easier to maintain.'),('Set A Weekly Check-In','Regular reviews help you catch missing transactions and reconcile records while they are still fresh.'),('Ask Questions Early','If an entry looks unusual, check it promptly. Accurate records help inform useful conversations with your accountant.')]),
 ('Tax','Preparing Your Records Before Tax Time',photos['architecture'],'Contemporary office buildings',[('Collect Relevant Documents','Keep income details, invoices, statements and other relevant records organised. Exactly what you need depends on your circumstances.'),('Check The Basics','Make sure information is complete and easy to follow. A little organisation can make review and preparation more straightforward.'),('Talk Through Uncertainties','Tax outcomes depend on current rules and your personal or business situation. Seek professional advice before making decisions or lodging.')]),
]
for slug,(cat,title,img,alt,parts) in zip(['cash-flow','bookkeeping','tax-readiness'],article_details):
 article=f'''<div class="article-hero"><div class="shell"><div class="article-head"><span class="eyebrow">{cat} Insights · Editorial Preview</span><h1>{title}</h1><p class="lead">A few practical ideas to help you feel more organised and informed.</p></div><div class="article-figure">{image(img,alt)}</div></div></div><section class="section"><div class="shell"><article class="article-content"><p>Good financial routines rarely need to be complicated. Consistency, clarity and a willingness to ask questions go a long way.</p>{''.join(f'<h2>{h}</h2><p>{p}</p>' for h,p in parts)}<div class="note">This article is illustrative general information for client review, not financial, accounting or tax advice. Individual circumstances and current regulations should be considered with a qualified professional.</div><a href="../insights.html" class="text-link article-back">{arrow} Back To All Insights</a></article></div></section>{cta('../')}'''
 (root/'insights'/f'{slug}.html').write_text(doc(f'{title} | Trendy Tax Solutions',f'Practical ideas about {cat.lower()} from Trendy Tax Solutions.',article,'insights.html','../'),encoding='utf-8')
privacy=heading('Privacy Information','Your Information Matters.','Website privacy information for the design preview.')+'''<section class="section"><div class="shell privacy-copy"><h2>Privacy Policy Pending Client Approval</h2><p>The final privacy policy has not yet been supplied or approved by Trendy Tax Solutions. This page is a design-stage notice, not a substitute for a complete Australian privacy policy.</p><h2>How This Preview Works</h2><p>There are no login accounts, customer dashboards or databases in this preview. Enquiry and newsletter forms create an email draft in your email application; they do not store or submit your data to this website.</p><p>Some pages display images hosted by Unsplash and Google Fonts. Those third-party providers may receive standard browser requests when their content loads.</p><h2>Questions</h2><p>Contact Trendy Tax Solutions at <a class="text-link" href="mailto:info@trendytaxsolutions.com.au">info@trendytaxsolutions.com.au</a>.</p></div></section>'''
(root/'privacy.html').write_text(doc('Privacy Information | Trendy Tax Solutions','Privacy information for the Trendy Tax Solutions design preview.',privacy,'',''),encoding='utf-8')
print('Wrote',len(list(root.rglob('*.html'))),'HTML files')
